let loadedRevision=db.modifiedAt||'';let stale=false;
document.body.classList.toggle('light',theme==='light');
function save(){if(stale){toast('This workspace changed in another tab. Reload before editing.');return false;}db.milestoneCategoryOrder=milestoneGroups().map(g=>g.name);db.modifiedAt=M.now();try{localStorage.setItem(STORE,JSON.stringify(db));loadedRevision=db.modifiedAt;storageIssue='';$('#save-state').textContent='Saved on this browser';return true;}catch(err){storageIssue='Browser storage unavailable or full. Export JSON to keep your changes.';$('#save-state').textContent='Export JSON to save';const status=$('.agenda-save-state');if(status){status.classList.add('has-warning');status.innerHTML=icon('alert')+'<span>Export a backup to keep changes</span>';}toast(storageIssue);return false;}}
