 window.PulseCover?.onRoute(route);PulseFX.cleanup();document.body.classList.toggle('is-cover',route==='cover');syncNav();$('#main').dataset.page=route;
 const about=route.startsWith('about-');$('#main').hidden=about;$('#about-view').hidden=!about;
 if(about){const i=Number(route.split('-')[1]);$('#about-title').textContent=aboutTitles[i-1];document.title='Pulse 5G | '+aboutTitles[i-1];sendAbout();return;}
 document.title='Pulse 5G | '+(route==='cover'?'Private 5G':route==='agenda'?'Project Overview':pageInfo(route).title);
 $('#main').innerHTML=(storageIssue?`<div class="warning-note">${e(storageIssue)} ${btn('Open Settings','settings','gear')}</div>`:'')+(route==='cover'?PulseCover.render():route==='agenda'?agenda():route==='assets'?assets():route==='team'?team():route==='raci'?raci():tracker(route));
 $('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');bindPage();PulseFX.enter($('#main'),navDirection);if($('#milestone-modal')?.open)refreshMilestoneTasks();if(window.PulsePIP?.isOpen())PulsePIP.refresh();
