function getRows(k){const dueFilter=['actions','milestones'].includes(k)&&['__overdue__','__soon__','__undated__'].includes(filter);let rows=I.filterRows(showDeleted?db.collections[k].filter(r=>r.deletedAt):active(k),S[k].fields,{query,status:dueFilter?'':filter,sort:sorts[k]});if(dueFilter)rows=rows.filter(r=>M.dueState(r).kind===filter.replaceAll('_',''));return rows;}
